      "tipo": "DrawCalls",
      "causa_raiz": "Emissão astronômica de Draw Calls atingindo o pico de 20.492 chamadas por frame (quase 8x o teto orçado de 2.579), provocando gargalo concomitante de GPU (até 43.89ms). Isso ocorre pela renderização individual de múltiplos objetos com materiais não instanciados ou instâncias independentes sem batching.",
      "codigo_refatorado": "using UnityEngine;

public class InstancedRendererManager : MonoBehaviour
{
    [SerializeField] private Mesh targetMesh;
    [SerializeField] private Material instancedMaterial;
    [SerializeField] private int instanceCount = 1000;
    [SerializeField] private float spawnRadius = 50f;

    private Matrix4x4[] matrices;
    private MaterialPropertyBlock propertyBlock;
    private static readonly int ColorProperty = Shader.PropertyToID("_BaseColor");

    private void Awake()
    {
        matrices = new Matrix4x4[instanceCount];
        propertyBlock = new MaterialPropertyBlock();
        Vector4[] colors = new Vector4[instanceCount];

        for (int i = 0; i < instanceCount; i++)
        {
            Vector3 pos = Random.insideUnitSphere * spawnRadius;
            Quaternion rot = Random.rotation;
            Vector3 scale = Vector3.one * Random.Range(0.8f, 1.2f);
            matrices[i] = Matrix4x4.TRS(pos, rot, scale);
            colors[i] = Random.ColorHSV();
        }

        propertyBlock.SetVectorArray(ColorProperty, colors);
    }

    private void Update()
    {
        if (targetMesh == null || instancedMaterial == null) return;
        int batchLimit = 1023;
        for (int i = 0; i < matrices.Length; i += batchLimit)
        {
            int currentCount = Mathf.Min(batchLimit, matrices.Length - i);
            Graphics.DrawMeshInstanced(targetMesh, 0, instancedMaterial, matrices, currentCount, propertyBlock, UnityEngine.Rendering.ShadowCastingMode.On, true, 0, null, UnityEngine.Rendering.LightProbeUsage.BlendProbes);
        }
    }
}",
      "explicacao_didatica": "Imagine o Draw Call como um garçom fazendo pedidos para a cozinha (a GPU). Chamar a cozinha 20.000 vezes para pedir um prato de cada vez trava o restaurante inteiro. Ao utilizar GPU Instancing e MaterialPropertyBlock, agrupamos milhares de itens idênticos (como vegetação, pedras ou detritos) em uma única folha de pedido de até 1.023 itens por remessa. Isso reduz milhares de Draw Calls para apenas uma ou duas chamadas, aliviando tanto o processador quanto a placa de vídeo."
    }
  ],
  "dicas_level_design": "1. Habilitar 'Enable GPU Instancing' em todos os shaders de materiais repetidos (vegetação, prop genérico, projéteis). 2. Implementar Occlusion Culling na cena para garantir que objetos escondidos atrás de paredes e terrenos não sejam desenhados. 3. Configurar LOD Groups (Level of Detail) com culling em distâncias médias para eliminar pequenos detalhes da GPU. 4. Agrupar texturas de objetos estáticos em Texture Atlases e marcar objetos imersos como 'Static' para usufruir de Static Batching. 5. Reduzir ou desligar a projeção de sombras em objetos pequenos (Shadow Casting Mode = Off)."
}

